// Generates src/generated/tokens.ts (React Native) and src/generated/tokens.css (web) from the design export.
// This is a build-time step: runtime code imports the generated files, never design/.
// Usage: node scripts/generate.mjs [--check]   (--check fails if the committed output is stale)
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const source = join(root, '../../design/claude-design/tokens.json');
const outDir = join(root, 'src/generated');
const check = process.argv.includes('--check');

const raw = JSON.parse(readFileSync(source, 'utf8'));

// The "label" group colours the canvas annotations (demo, planned, clinical, translation markers). They are design
// tooling, not product UI, so they are not generated.
const RUNTIME_COLOR_GROUPS = ['surface', 'text', 'accent', 'clinical'];

const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());

function palette(mode) {
  const out = {};
  for (const group of RUNTIME_COLOR_GROUPS) {
    const g = raw.color[group];
    if (!g) throw new Error(`tokens.json is missing color.${group}`);
    for (const [name, v] of Object.entries(g)) {
      if (!/^#[0-9A-F]{6}$/i.test(v[mode])) throw new Error(`color.${group}.${name}.${mode} is not #RRGGBB`);
      // Group and name are combined so "accent.accent" becomes "accent" and "surface.bg" becomes "surfaceBg".
      const key = group === 'accent' || group === 'text' || group === 'clinical' ? camel(name) : camel(`${group}-${name}`);
      if (key in out) throw new Error(`duplicate colour key ${key}`);
      out[key] = v[mode].toUpperCase();
    }
  }
  // The destructive button on board 12 is drawn with the clinical annotation pair. It is exposed under a product
  // name so that no annotation colour is used directly (design gap G-17).
  for (const [key, name] of [['dangerBg', 'clinical-bg'], ['dangerText', 'clinical-text']]) {
    const v = raw.color.label?.[name]?.[mode];
    if (!v) throw new Error(`tokens.json is missing color.label.${name}.${mode}`);
    out[key] = v.toUpperCase();
  }
  return out;
}

const day = palette('day');
const night = palette('night');

const type = {};
for (const [name, [size, lineHeight, weight]] of Object.entries(raw.type)) {
  type[camel(name)] = { fontSize: size, lineHeight, fontWeight: weight };
}

const space = Object.fromEntries(Object.entries(raw.space).map(([k, v]) => [k, v]));
const radius = Object.fromEntries(Object.entries(raw.radius).map(([k, v]) => [camel(k), v]));
const motion = Object.fromEntries(Object.entries(raw.motion).map(([k, v]) => [camel(k), v]));
const size = Object.fromEntries(Object.entries(raw.size).map(([k, v]) => [camel(k), v]));
const breakpoint = Object.fromEntries(Object.entries(raw.breakpoint).map(([k, v]) => [camel(k), v]));
const elevation = Object.fromEntries(Object.entries(raw.elevation).map(([k, v]) => [camel(k), v]));

const header = '// GENERATED by packages/tokens/scripts/generate.mjs from design/claude-design/tokens.json. Do not edit.\n';
const lit = (o) => JSON.stringify(o, null, 2);

const ts =
  header +
  `export const day = ${lit(day)} as const;\n\n` +
  `export const night = ${lit(night)} as const;\n\n` +
  `/** [fontSize, lineHeight, design weight]. Weight 650 is a variable-font weight; see fontWeightNative. */\n` +
  `export const type = ${lit(type)} as const;\n\n` +
  `export const space = ${lit(space)} as const;\n\n` +
  `export const radius = ${lit(radius)} as const;\n\n` +
  `/** Durations in ms; easings are CSS cubic-bezier strings. */\n` +
  `export const motion = ${lit(motion)} as const;\n\n` +
  `export const size = ${lit(size)} as const;\n\n` +
  `export const breakpoint = ${lit(breakpoint)} as const;\n\n` +
  `/** CSS values as drawn. Native equivalents are in elevationNative (src/index.ts). */\n` +
  `export const elevation = ${lit(elevation)} as const;\n`;

const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const cssVars = (p) =>
  Object.entries(p)
    .map(([k, v]) => `  --${kebab(k)}: ${v};`)
    .join('\n');
const css =
  header.replace('//', '/*').replace('\n', ' */\n') +
  `:root, [data-theme='day'] {\n  color-scheme: light;\n${cssVars(day)}\n}\n\n` +
  `[data-theme='night'] {\n  color-scheme: dark;\n${cssVars(night)}\n}\n\n` +
  `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme='day']) {\n    color-scheme: dark;\n${cssVars(night).replace(/^/gm, '  ')}\n  }\n}\n`;

const files = { 'tokens.ts': ts, 'tokens.css': css };
let stale = false;
mkdirSync(outDir, { recursive: true });
for (const [name, content] of Object.entries(files)) {
  const path = join(outDir, name);
  if (check) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) {
      console.error(`stale: src/generated/${name} (run pnpm --filter @steady/tokens build)`);
      stale = true;
    }
  } else {
    writeFileSync(path, content);
    console.log(`wrote src/generated/${name}`);
  }
}
if (stale) process.exit(1);
if (check) console.log('generated tokens are up to date');
